// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.datastoreimport android.content.Contextimport androidx.datastore.core.DataStoreimport androidx.datastore.preferences.core.Preferencesimport androidx.datastore.preferences.core.booleanPreferencesKeyimport androidx.datastore.preferences.core.editimport androidx.datastore.preferences.core.intPreferencesKeyimport androidx.datastore.preferences.core.stringPreferencesKeyimport androidx.datastore.preferences.preferencesDataStoreimport dagger.hilt.android.qualifiers.ApplicationContextimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.mapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — typed preferences (DataStore). * * Stores privacy settings, feature flags, and user preferences. * * For Module 1, this is a basic PreferencesDataStore. Module 3 will add * a typed Proto DataStore for memory snapshots, and Module 11 will wrap * this with encryption (EncryptedDataStore). */private val Context.nousDataStore: DataStore<Preferences> by preferencesDataStore(    name = "nous_prefs",)@Singletonclass NousPreferences @Inject constructor(    @ApplicationContext private val context: Context,) {    // ─── Privacy settings (default OFF — see ADR 0011) ─────────────────────    val cloudLlmEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_CLOUD_LLM_ENABLED] ?: false }    val crashReportingEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_CRASH_REPORTING_ENABLED] ?: false }    val anonymousTelemetryEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_ANONYMOUS_TELEMETRY_ENABLED] ?: false }    val wakeWordEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_WAKE_WORD_ENABLED] ?: false }    val voiceBiometricsEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_VOICE_BIOMETRICS_ENABLED] ?: false }    val ambientAwarenessEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_AMBIENT_AWARENESS_ENABLED] ?: false }    val multiDeviceSyncEnabled: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_MULTI_DEVICE_SYNC_ENABLED] ?: false }    // ─── Active persona ────────────────────────────────────────────────────    val activePersonaId: Flow<String> = context.nousDataStore.data        .map { it[KEY_ACTIVE_PERSONA] ?: "jarvis" }  // default = JARVIS    // ─── LLM model ─────────────────────────────────────────────────────────    val activeLocalModelId: Flow<String?> = context.nousDataStore.data        .map { it[KEY_ACTIVE_LOCAL_MODEL] }    // ─── Onboarding ────────────────────────────────────────────────────────    val onboardingCompleted: Flow<Boolean> = context.nousDataStore.data        .map { it[KEY_ONBOARDING_COMPLETED] ?: false }    val activeModelCatalogUrl: Flow<String> = context.nousDataStore.data        .map { it[KEY_MODEL_CATALOG_URL] ?: DEFAULT_MODEL_CATALOG_URL }    // ─── Mutators ──────────────────────────────────────────────────────────    suspend fun setCloudLlmEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_CLOUD_LLM_ENABLED] = enabled }    }    suspend fun setCrashReportingEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_CRASH_REPORTING_ENABLED] = enabled }    }    suspend fun setAnonymousTelemetryEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_ANONYMOUS_TELEMETRY_ENABLED] = enabled }    }    suspend fun setWakeWordEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_WAKE_WORD_ENABLED] = enabled }    }    suspend fun setVoiceBiometricsEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_VOICE_BIOMETRICS_ENABLED] = enabled }    }    suspend fun setAmbientAwarenessEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_AMBIENT_AWARENESS_ENABLED] = enabled }    }    suspend fun setMultiDeviceSyncEnabled(enabled: Boolean) {        context.nousDataStore.edit { it[KEY_MULTI_DEVICE_SYNC_ENABLED] = enabled }    }    suspend fun setActivePersona(personaId: String) {        context.nousDataStore.edit { it[KEY_ACTIVE_PERSONA] = personaId }    }    suspend fun setActiveLocalModel(modelId: String?) {        context.nousDataStore.edit {            if (modelId == null) it.remove(KEY_ACTIVE_LOCAL_MODEL)            else it[KEY_ACTIVE_LOCAL_MODEL] = modelId        }    }    suspend fun setOnboardingCompleted(completed: Boolean) {        context.nousDataStore.edit { it[KEY_ONBOARDING_COMPLETED] = completed }    }    suspend fun setActiveModelCatalogUrl(url: String) {        context.nousDataStore.edit { it[KEY_MODEL_CATALOG_URL] = url }    }    // ─── Wipe (for "delete all my data") ───────────────────────────────────    suspend fun wipe() {        context.nousDataStore.edit { it.clear() }    }    private companion object {        val KEY_CLOUD_LLM_ENABLED = booleanPreferencesKey("cloud_llm_enabled")        val KEY_CRASH_REPORTING_ENABLED = booleanPreferencesKey("crash_reporting_enabled")        val KEY_ANONYMOUS_TELEMETRY_ENABLED = booleanPreferencesKey("anonymous_telemetry_enabled")        val KEY_WAKE_WORD_ENABLED = booleanPreferencesKey("wake_word_enabled")        val KEY_VOICE_BIOMETRICS_ENABLED = booleanPreferencesKey("voice_biometrics_enabled")        val KEY_AMBIENT_AWARENESS_ENABLED = booleanPreferencesKey("ambient_awareness_enabled")        val KEY_MULTI_DEVICE_SYNC_ENABLED = booleanPreferencesKey("multi_device_sync_enabled")        val KEY_ACTIVE_PERSONA = stringPreferencesKey("active_persona")        val KEY_ACTIVE_LOCAL_MODEL = stringPreferencesKey("active_local_model")        val KEY_ONBOARDING_COMPLETED = booleanPreferencesKey("onboarding_completed")        val KEY_MODEL_CATALOG_URL = stringPreferencesKey("model_catalog_url")        const val DEFAULT_MODEL_CATALOG_URL =            "https://raw.githubusercontent.com/roshan/nous-models/main/catalog.json"    }}